SELECT 'versions' test,jsonb_agg(x) data FROM (SELECT normalization_version,count(*) n FROM core.ted_notices GROUP BY 1) x
UNION ALL SELECT 'competition_mismatch',to_jsonb(x) FROM (SELECT count(*) n,count(*) FILTER(WHERE cc.is_single_bidder IS DISTINCT FROM (cc.tenders_received=1)) invalid_boolean,count(*) FILTER(WHERE cc.tenders_received IS DISTINCT FROM l.tenders_received) wrong_count,count(*) FILTER(WHERE cc.match_score<0.9 OR l.amount_details->>'matchEligible' IS DISTINCT FROM 'true' OR l.currency IS DISTINCT FROM 'RON') ineligible_source FROM marts.contract_competition cc LEFT JOIN core.ted_lot_results l ON l.id=cc.ted_lot_result_id) x
UNION ALL SELECT 'ted_value_stats',to_jsonb(x) FROM (SELECT count(*) FILTER(WHERE total_ron IS NOT NULL) summed_monetary_rows FROM marts.ted_stats) x
UNION ALL SELECT 'sample_references',to_jsonb(x) FROM (SELECT count(*) n,count(*) FILTER(WHERE f.id IS NULL) missing_flag,count(*) FILTER(WHERE f.id IS NOT NULL AND (i.flag_code IS DISTINCT FROM f.flag_code OR i.evidence IS DISTINCT FROM f.evidence)) changed_flag FROM marts.flag_instances i LEFT JOIN core.flags f ON f.id=i.id) x
